// Places through both adapters: what a base URL, its query, and the request's context make of the reads and the
// release, and which detection reply a not-honored result discards (C14).

import omp from "../../omp/src/index.ts";
import pi from "../../pi/src/index.ts";
import { scenarios, type Adapter, type Scenario, type Step, type Wire } from "./fake-harness.ts";
import { SHAPES, type Expected } from "./wire.ts";

const ADAPTERS: readonly Adapter[] = [
  { name: "omp", register: omp, headerHook: false },
  { name: "pi", register: pi, headerHook: true },
];

const NOT_HONORED = { status: 200, body: { choices: [] } };
const COBALT_ONLY = { status: 200, body: { data: [{ id: "demo-model", routes: [{ provider: "cobalt", facts: "" }] }] } };
const K2 = { auth: { result: { ok: true, apiKey: "k2" } }, wire: { key: "k2" } } as const;
const K1 = { auth: { result: { ok: true, apiKey: "demo-key" } }, wire: { key: "demo-key" } } as const;
/** One request per way the transport can hand it to fetch, each with `wire` otherwise. */
const overShapes = (wire: Wire): Step[] => SHAPES.flatMap((shape): Step[] => [{ do: "set", wire: { ...wire, shape } }, { do: "request" }]);
/**
 * The same, each request prepared and then sent after its session ends, which revokes its release and removes
 * its watcher; with `expire`, sent only once the revoked release has expired, so nothing is held.
 */
const afterShutdown = (wire: Wire, expire = false): Step[] =>
  SHAPES.flatMap((shape): Step[] => [
    { do: "set", wire: { ...wire, shape } },
    { do: "prepare", id: shape },
    { do: "emit", event: "session_shutdown" },
    ...(expire ? [{ do: "tick", ms: 30_000 } as const] : []),
    { do: "send", id: shape },
  ]);

